mod solution;

fn main() {
    let cases = [
    (r#"next=[1,2,3,1]"#, r#"1"#),
    (r#"next=[1,2,0]"#, r#"0"#),
    (r#"
next=[1,2,0]
"#, r#"0"#),
    (r#"  
next=[1,2,3,1]
  "#, r#"1"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS floyd-state-cycle");
}
